test("Lee Sin evidence aliases resolve into geometry and rig without mutating authored IR", () => {
    const wide = createLeeSinV2CharacterIR();
    const narrow = createLeeSinV2CharacterIR();
    const wideEvidence = wide.evidence.proportions.find((item) => item.id === "arm-span");
    const narrowEvidence = narrow.evidence.proportions.find((item) => item.id === "arm-span");
    wideEvidence.ratio = 1.31;
    wideEvidence.confidence = 1;
    narrowEvidence.ratio = 1.0;
    narrowEvidence.confidence = 1;
    const wideCompiled = compileCharacter(wide);
    const narrowCompiled = compileCharacter(narrow);
    const wideHand = wideCompiled.meshes.get("left-hand");
    const narrowHand = narrowCompiled.meshes.get("left-hand");
    wideHand.geometry.computeBoundingBox();
    narrowHand.geometry.computeBoundingBox();
    assert.equal(wide.proportionModel.armSpan, 1.31, "compile must not mutate authored CharacterIR");
    assert.equal(narrow.proportionModel.armSpan, 1.31, "compile must not mutate authored CharacterIR");
    assert.equal(narrowCompiled.ir.proportionModel.armSpan, 1.0);
    assert.ok(wideHand.geometry.boundingBox.max.x > narrowHand.geometry.boundingBox.max.x + 0.1);
    assert.ok(wideCompiled.skeleton.restWorldPositions.get("left-wrist").x > narrowCompiled.skeleton.restWorldPositions.get("left-wrist").x + 0.08);
});
